const miChatId = $('Telegram Trigger').item.json.message.chat.id.toString();
const eventos = $input.all();

const misCitas = eventos.filter(e => 
  e.json.description?.includes(`chat_id: ${miChatId}`)
);

if (misCitas.length === 0) {
  return [{ json: { text: '📭 No tenés citas agendadas.' } }];
}

const mensajes = misCitas.map(e => {
  const titulo = e.json.summary || 'Sin título';
  const inicio = e.json.start?.dateTime || e.json.start?.date;
  const fecha = new Date(inicio).toLocaleString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires',
    dateStyle: 'short',
    timeStyle: 'short'
  });
  return `📅 <b>${titulo}</b>\n🕐 ${fecha}`;
});

return [{ json: { text: `⏰ Tus citas:\n\n${mensajes.join('\n\n')}` } }];

