    }
  };
} else {
  return {
    json: {
      encontrado: false,
      error_msg: "Ese número no está en la lista. Mandame uno válido."
    }
  };
}

const output = $('AI Agent2').first().json.output;
const clean = output.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(clean);

if (parsed.error) {
  return { json: { fecha: null, hora: null, datetime_iso: null, error: parsed.error } };
}

const ahora = Date.now();
const fechaDeseada = new Date(parsed.datetime_iso); 

if (fechaDeseada.getTime() <= ahora) {
  return { json: { fecha: null, hora: null, datetime_iso: null, error: "Esa fecha y hora ya pasaron. Elegí un momento futuro." } };
}

return {
  json: {
    fecha: parsed.fecha,
    hora: parsed.hora,
    datetime_iso: parsed.datetime_iso,
    error: null
  }
};

