const chatId = $('Telegram Trigger').item.json.message.chat.id.toString();
const fecha = $('cambia de texto a json,modifica sheet').item.json.fecha;
const hora = $('cambia de texto a json,modifica sheet').item.json.hora;
const eventIdActual = $('cambia de texto a json,modifica sheet').item.json.event_id || null;

// Forzamos la conversión correcta a UTC
const fechaDeseada = new Date(`${fecha}T${hora}:00.000-03:00`);
const fechaFin = new Date(fechaDeseada.getTime() + 60 * 60 * 1000);

const eventos = $input.all();

const hayConflicto = eventos.some(e => {
  if (!e.json.start?.dateTime) return false;
  if (eventIdActual && e.json.id === eventIdActual) return false;

  const inicio = new Date(e.json.start.dateTime);
  const fin = new Date(e.json.end.dateTime);

  // Comparamos todo en millisegundos UTC
  return fechaDeseada.getTime() <= fin.getTime() && fechaFin.getTime() > inicio.getTime();
});

return [{ json: { 
  hayConflicto, 
  fechaDeseada: fechaDeseada.toISOString(), 
  fechaFin: fechaFin.toISOString() 
} }];

